//go:build darwin || linux

package workspace

import (
 "os"
 "path/filepath"
 "testing"
)

func TestReviewWorkspaceReplacementPreservesOperatorPermissions(t *testing.T) {
 path := filepath.Join(t.TempDir(), "workspace")
 oldCatalog, oldIdentity := testCatalog(t, "old", "Old")
 if _, err := Project(t.Context(), path, oldCatalog, oldIdentity); err != nil { t.Fatal(err) }
 if err := os.Chmod(path, 0o770); err != nil { t.Fatal(err) }
 note := filepath.Join(path, "private-notes.txt")
 if err := os.WriteFile(note, []byte("operator note"), 0o600); err != nil { t.Fatal(err) }
 if err := os.Chmod(note, 0o600); err != nil { t.Fatal(err) }
 next, identity := testCatalog(t, "new", "New")
 if _, err := Project(t.Context(), path, next, identity); err != nil { t.Fatal(err) }
 for name, want := range map[string]os.FileMode{path: 0o770, note: 0o600} {
  info, err := os.Stat(name); if err != nil { t.Fatal(err) }
  if got := info.Mode().Perm(); got != want { t.Errorf("%s mode changed: got %04o, want %04o", filepath.Base(name), got, want) }
 }
}

